466: let motionWatchdog = null;
467: 
468: function orientationAngle() {
469:   if (screen.orientation && typeof screen.orientation.angle === "number") return screen.orientation.angle;
470:   return typeof window.orientation === "number" ? window.orientation : 0;
471: }
472: 
473: function handleOrientation(event) {
474:   if (event.beta == null && event.gamma == null) return;
475:   const beta = event.beta || 0;
476:   const gamma = event.gamma || 0;
477:   input.tilt.seen = true;
478:   if (!input.tilt.ready) {
479:     input.tilt.ready = true;
480:     input.tilt.base = { beta, gamma };
481:     updateMotionUI();
482:     return;
483:   }
484:   if (!input.tilt.base) input.tilt.base = { beta, gamma };
485: 
486:   let dx = gamma - input.tilt.base.gamma;
487:   let dy = beta - input.tilt.base.beta;
488:   const radians = orientationAngle() * Math.PI / 180;
489:   if (radians) {
490:     const cos = Math.cos(radians);
491:     const sin = Math.sin(radians);
492:     const rotatedX = dx * cos + dy * sin;
493:     const rotatedY = -dx * sin + dy * cos;
494:     dx = rotatedX;
495:     dy = rotatedY;
496:   }
497: 
498:   if (Math.hypot(dx, dy) > 3.6) {
499:     input.tilt.angle = Math.atan2(dy, dx);
500:     input.tilt.active = true;
501:   } else {
502:     input.tilt.active = false;
503:   }
504: }
505: 
506: function disableMotion(keepToast = false) {
507:   if (!input.tilt.enabled) return;
508:   input.tilt.enabled = false;
509:   input.tilt.ready = false;
510:   input.tilt.active = false;
511:   input.tilt.base = null;
512:   window.removeEventListener("deviceorientation", handleOrientation, true);
513:   if (motionWatchdog) clearTimeout(motionWatchdog);
514:   motionWatchdog = null;
515:   updateMotionUI();
516:   if (!keepToast) toast("Inclinaison désactivée. Joysticks uniquement.");
517: }
518: 
519: async function toggleMotion() {
520:   sound.unlock();
521:   if (input.tilt.enabled) {
522:     disableMotion();
523:     return;
524:   }
525:   if (!("DeviceOrientationEvent" in window)) {
526:     toast("Cet appareil ne fournit pas de capteur d'orientation.");
527:     return;
528:   }
529:   if (typeof DeviceOrientationEvent.requestPermission === "function") {
530:     try {
531:       const permission = await DeviceOrientationEvent.requestPermission();
532:       if (permission !== "granted") {
533:         toast("Autorisation de mouvement refusée. Les joysticks restent actifs.");
534:         return;
535:       }
536:     } catch {
537:       toast("Impossible de demander l'accès au mouvement.");
538:       return;
539:     }
540:   }
541: 
542:   input.tilt.enabled = true;
543:   input.tilt.ready = false;
544:   input.tilt.active = false;
545:   input.tilt.base = null;
546:   input.tilt.seen = false;
547:   window.addEventListener("deviceorientation", handleOrientation, true);
548:   updateMotionUI();
549:   toast("Inclinez l'appareil pour viser. Le tir est automatique.");
550: 
551:   if (motionWatchdog) clearTimeout(motionWatchdog);
552:   motionWatchdog = setTimeout(() => {
553:     motionWatchdog = null;
554:     if (!input.tilt.enabled || input.tilt.seen) return;
555:     disableMotion(true);
556:     toast("Aucun capteur détecté. Les joysticks restent disponibles.");
557:   }, 2200);
558: }
