774: function resize() {
775:   view.w = window.innerWidth;
776:   view.h = window.innerHeight;
777:   view.dpr = Math.min(window.devicePixelRatio || 1, 2);
778:   view.scale = clamp(Math.min(view.w / 680, view.h / 700), 0.82, 1.22);
779:   ui.canvas.width = Math.round(view.w * view.dpr);
780:   ui.canvas.height = Math.round(view.h * view.dpr);
781:   ui.canvas.style.width = `${view.w}px`;
782:   ui.canvas.style.height = `${view.h}px`;
783:   const coarse = window.matchMedia("(pointer: coarse)").matches;
784:   isTouchMode = coarse || view.w <= 900;
785:   document.body.classList.toggle("is-touch", isTouchMode);
786:   ui.desktopHint.classList.toggle("hidden", isTouchMode);
787:   buildScreenSprites();
788:   clampCamera();
789:   menuDirty = true;
790: }
