792: function buildScreenSprites() {
793:   const dpr = view.dpr;
794:   const w = Math.max(1, Math.round(view.w * dpr));
795:   const h = Math.max(1, Math.round(view.h * dpr));
796: 
797:   vignetteSprite = document.createElement("canvas");
798:   vignetteSprite.width = w;
799:   vignetteSprite.height = h;
800:   let c = vignetteSprite.getContext("2d");
801:   const vignette = c.createRadialGradient(
802:     w / 2, h / 2, Math.min(w, h) * 0.2,
