837: function visibleHalf() {
838:   return {
839:     x: view.w / (2 * view.scale),
840:     y: view.h / (2 * view.scale)
841:   };
842: }
843: 
844: function cameraBounds() {
845:   const half = visibleHalf();
846:   return {
847:     minX: Math.min(half.x, WORLD.w / 2),
848:     maxX: Math.max(WORLD.w - half.x, WORLD.w / 2),
849:     minY: Math.min(half.y, WORLD.h / 2),
850:     maxY: Math.max(WORLD.h - half.y, WORLD.h / 2)
851:   };
852: }
853: 
854: function clampCamera() {
855:   const bounds = cameraBounds();
856:   camera.x = clamp(camera.x, bounds.minX, bounds.maxX);
857:   camera.y = clamp(camera.y, bounds.minY, bounds.maxY);
858: }
859: 
860: function screenToWorld(x, y) {
861:   return {
862:     x: (x - view.w / 2) / view.scale + camera.x,
863:     y: (y - view.h / 2) / view.scale + camera.y
864:   };
865: }
