1316: function damageZombie(zombie, damage, angle) {
1317:   if (zombie.dead) return;
1318:   zombie.hp -= damage;
1319:   zombie.hitFlash = 1;
1320:   const force = zombie.type === "brute" ? 32 : 78;
1321:   zombie.knockX += Math.cos(angle) * force;
1322:   zombie.knockY += Math.sin(angle) * force;
1323:   const headX = zombie.x + Math.cos(zombie.angle) * zombie.r * 0.35;
1324:   const headY = zombie.y + Math.sin(zombie.angle) * zombie.r * 0.35;
1325:   bloodBurst(headX, headY, zombie.type === "brute" ? 7 : 4, 0.9);
1326:   sound.hit();
1327:   if (zombie.hp <= 0) killZombie(zombie, angle);
1328: }
