1330: function killZombie(zombie, angle) {
1331:   if (zombie.dead) return;
1332:   zombie.dead = true;
1333:   game.kills += 1;
1334:   game.combo += 1;
1335:   game.comboT = 3;
1336:   const multiplier = 1 + Math.min(4, Math.floor((game.combo - 1) / 4));
