1048:   const roll = Math.random();
1049:   if (wave >= 4 && roll < Math.min(0.2, 0.06 + wave * 0.012)) return "brute";
1050:   if (wave >= 2 && roll < 0.24 + Math.min(0.26, wave * 0.022)) return "runner";
1051:   return "walker";
