1059:   const count = Math.min(42, 5 + Math.round(wave * 2.35));
1060:   const interval = Math.max(0.24, 0.54 - wave * 0.018);
1061:   for (let i = 0; i < count; i += 1) {
1062:     game.spawnQueue.push({
1063:       type: rollEnemyType(wave),
1064:       at: 0.55 + i * interval + rand(-0.08, 0.14)
1065:     });
1066:   }
1067:   game.spawnQueue.sort((a, b) => a.at - b.at);
1068:   banner(`VAGUE ${String(wave).padStart(2, "0")}`, wave >= 10 ? "ENFER" : "NOUVELLE VAGUE", `${count} HOSTILES EN APPROCHE`);
1069:   sound.wave();
