308: function stickVector(dx, dy, radius) {
309:   let nx = dx / radius;
310:   let ny = dy / radius;
311:   let magnitude = Math.hypot(nx, ny);
312:   if (magnitude < 0.13) return { x: 0, y: 0, mag: 0 };
313:   if (magnitude > 1) {
314:     nx /= magnitude;
315:     ny /= magnitude;
316:     magnitude = 1;
317:   }
318:   const normalized = clamp((magnitude - 0.13) / 0.87, 0, 1);
319:   return { x: nx * normalized, y: ny * normalized, mag: normalized };
320: }
321: 
322: function setupStick(element, onMove, onEnd) {
323:   let pointerId = null;
324:   let centerX = 0;
325:   let centerY = 0;
326:   let radius = 1;
327:   const knob = element.querySelector(".stick-knob");
328: 
329:   function apply(event) {
330:     if (event.pointerId !== pointerId) return;
331:     let dx = event.clientX - centerX;
332:     let dy = event.clientY - centerY;
333:     const distance = Math.hypot(dx, dy);
334:     if (distance > radius) {
335:       dx = dx / distance * radius;
336:       dy = dy / distance * radius;
337:     }
338:     const vector = stickVector(dx, dy, radius);
339:     knob.style.transform = `translate(${dx.toFixed(1)}px, ${dy.toFixed(1)}px)`;
340:     onMove(vector, Math.atan2(dy, dx));
341:   }
342: 
343:   element.addEventListener("pointerdown", (event) => {
344:     if (pointerId !== null) return;
345:     event.preventDefault();
346:     sound.unlock();
347:     pointerId = event.pointerId;
348:     const rect = element.getBoundingClientRect();
349:     centerX = rect.left + rect.width / 2;
350:     centerY = rect.top + rect.height / 2;
351:     radius = rect.width * 0.31;
352:     element.classList.add("active");
353:     element.setPointerCapture?.(pointerId);
354:     apply(event);
355:   });
356: 
357:   element.addEventListener("pointermove", (event) => {
358:     if (pointerId === null) return;
359:     event.preventDefault();
360:     apply(event);
361:   });
362: 
363:   function release(event) {
364:     if (event.pointerId !== pointerId) return;
365:     pointerId = null;
366:     element.classList.remove("active");
367:     knob.style.transform = "translate(0px, 0px)";
368:     onEnd();
369:   }
370: 
371:   element.addEventListener("pointerup", release);
372:   element.addEventListener("pointercancel", release);
373:   element.addEventListener("lostpointercapture", () => {
374:     if (pointerId === null) return;
375:     pointerId = null;
376:     element.classList.remove("active");
377:     knob.style.transform = "translate(0px, 0px)";
378:     onEnd();
379:   });
380: }
