590: function paintGround(c) {
591:   const random = mulberry32(8841);
592:   c.fillStyle = "#151b13";
593:   c.fillRect(0, 0, WORLD.w, WORLD.h);
594: 
595:   const wash = c.createLinearGradient(0, 0, WORLD.w, WORLD.h);
596:   wash.addColorStop(0, "rgba(36, 52, 32, 0.35)");
597:   wash.addColorStop(0.42, "rgba(18, 26, 16, 0.1)");
598:   wash.addColorStop(0.7, "rgba(44, 58, 35, 0.22)");
599:   wash.addColorStop(1, "rgba(9, 14, 9, 0.42)");
600:   c.fillStyle = wash;
601:   c.fillRect(0, 0, WORLD.w, WORLD.h);
602: 
603:   for (let i = 0; i < 34; i += 1) {
604:     const x = random() * WORLD.w;
605:     const y = random() * WORLD.h;
606:     const radius = 110 + random() * 430;
607:     const moss = c.createRadialGradient(x, y, 0, x, y, radius);
608:     const green = 40 + Math.floor(random() * 26);
609:     moss.addColorStop(0, `rgba(${green - 10}, ${green + 16}, ${green - 12}, ${0.07 + random() * 0.09})`);
610:     moss.addColorStop(0.65, `rgba(${green - 16}, ${green + 4}, ${green - 14}, ${0.03 + random() * 0.05})`);
611:     moss.addColorStop(1, "rgba(0,0,0,0)");
612:     c.fillStyle = moss;
613:     c.fillRect(x - radius, y - radius, radius * 2, radius * 2);
614:   }
615: 
616:   for (let i = 0; i < 26000; i += 1) {
617:     const value = 20 + Math.floor(random() * 38);
618:     c.fillStyle = `rgba(${value}, ${value + 8}, ${Math.max(12, value - 3)}, ${0.1 + random() * 0.22})`;
619:     const s = random() < 0.88 ? 1 : 2;
620:     c.fillRect(random() * WORLD.w, random() * WORLD.h, s, s);
621:   }
622: 
623:   for (let i = 0; i < 210; i += 1) {
624:     c.strokeStyle = `rgba(5, 8, 5, ${0.16 + random() * 0.26})`;
625:     c.lineWidth = 0.8 + random() * 1.3;
626:     let x = random() * WORLD.w;
627:     let y = random() * WORLD.h;
628:     c.beginPath();
629:     c.moveTo(x, y);
630:     const segments = 2 + Math.floor(random() * 5);
631:     for (let j = 0; j < segments; j += 1) {
632:       x += (random() - 0.5) * 64;
633:       y += (random() - 0.5) * 64;
634:       c.lineTo(x, y);
635:     }
636:     c.stroke();
637:   }
638: 
639:   for (let i = 0; i < 850; i += 1) {
640:     const x = random() * WORLD.w;
641:     const y = random() * WORLD.h;
642:     c.fillStyle = `rgba(${48 + random() * 40}, ${50 + random() * 38}, ${42 + random() * 26}, ${0.18 + random() * 0.25})`;
643:     c.beginPath();
644:     c.ellipse(x, y, 1 + random() * 3.6, 1 + random() * 2, random() * TAU, 0, TAU);
645:     c.fill();
646:   }
647: 
648:   for (let i = 0; i < 900; i += 1) {
649:     const x = random() * WORLD.w;
650:     const y = random() * WORLD.h;
651:     const length = 2 + random() * 7;
652:     c.strokeStyle = `rgba(${40 + random() * 30}, ${58 + random() * 42}, ${32 + random() * 20}, ${0.18 + random() * 0.27})`;
653:     c.lineWidth = 1;
654:     c.beginPath();
655:     c.moveTo(x, y);
656:     c.lineTo(x + (random() - 0.5) * 5, y - length);
657:     c.stroke();
658:   }
659: }
