837: function visibleHalf() {
838:   return {
839:     x: view.w / (2 * view.scale),
840:     y: view.h / (2 * view.scale)
841:   };
842: }
843: 
844: function cameraBounds() {
845:   const half = visibleHalf();
846:   return {
847:     minX: Math.min(half.x, WORLD.w / 2),
848:     maxX: Math.max(WORLD.w - half.x, WORLD.w / 2),
849:     minY: Math.min(half.y, WORLD.h / 2),
850:     maxY: Math.max(WORLD.h - half.y, WORLD.h / 2)
851:   };
852: }
853: 
854: function clampCamera() {
855:   const bounds = cameraBounds();
856:   camera.x = clamp(camera.x, bounds.minX, bounds.maxX);
857:   camera.y = clamp(camera.y, bounds.minY, bounds.maxY);
858: }
859: 
860: function screenToWorld(x, y) {
861:   return {
862:     x: (x - view.w / 2) / view.scale + camera.x,
863:     y: (y - view.h / 2) / view.scale + camera.y
864:   };
865: }
866: 
867: function updateCamera(dt) {
868:   const bounds = cameraBounds();
869:   let targetX = player.x;
870:   let targetY = player.y;
871:   if (game.mode === "menu" || game.mode === "gameover") {
872:     targetX = WORLD.w / 2 + Math.sin(game.time * 0.12) * 85;
873:     targetY = WORLD.h / 2 + Math.cos(game.time * 0.1) * 60;
874:   }
875:   targetX = clamp(targetX, bounds.minX, bounds.maxX);
876:   targetY = clamp(targetY, bounds.minY, bounds.maxY);
877:   const smoothing = 1 - Math.exp(-dt * (game.mode === "menu" ? 2 : 7));
878:   camera.x += (targetX - camera.x) * smoothing;
879:   camera.y += (targetY - camera.y) * smoothing;
880: }
