1200: function updatePlayer(dt) {
1201:   player.invuln = Math.max(0, player.invuln - dt);
1202:   player.flash = Math.max(0, player.flash - dt);
1203:   player.recoil = Math.max(0, player.recoil - dt * 4.8);
1204: 
1205:   let mx = 0;
1206:   let my = 0;
1207:   if (input.keys.has("left")) mx -= 1;
1208:   if (input.keys.has("right")) mx += 1;
1209:   if (input.keys.has("up")) my -= 1;
1210:   if (input.keys.has("down")) my += 1;
1211:   mx += input.move.x;
1212:   my += input.move.y;
1213:   const length = Math.hypot(mx, my);
1214:   if (length > 1) {
1215:     mx /= length;
1216:     my /= length;
1217:   }
1218:   player.x = clamp(player.x + mx * player.speed * dt, 25, WORLD.w - 25);
1219:   player.y = clamp(player.y + my * player.speed * dt, 25, WORLD.h - 25);
1220:   player.walk += Math.hypot(mx, my) * dt * 9;
1221: 
1222:   const usingStick = input.aimStick.mag > 0.16;
1223:   if (usingStick) {
1224:     player.aim = Math.atan2(input.aimStick.y, input.aimStick.x);
1225:   } else if (input.mouse.active && !isTouchMode) {
1226:     const target = screenToWorld(input.mouse.x, input.mouse.y);
1227:     player.aim = Math.atan2(target.y - player.y, target.x - player.x);
1228:   } else if (input.tilt.enabled && input.tilt.ready) {
1229:     player.aim = angleLerp(player.aim, input.tilt.angle, 1 - Math.exp(-dt * 14));
1230:   }
1231: 
1232:   if ((usingStick || input.tilt.enabled) && enemies.length > 0) applyAimAssist(dt);
1233: 
1234:   const wantFire = input.mouse.down
1235:     || input.keys.has("fire")
1236:     || input.aimStick.mag > 0.3
1237:     || (input.tilt.enabled && input.tilt.ready);
1238: 
1239:   player.fireCd = Math.max(0, player.fireCd - dt);
1240: 
1241:   if (player.reloading) {
1242:     player.reloadT -= dt;
1243:     if (player.reloadT <= 0) {
1244:       player.reloading = false;
1245:       player.reloadT = 0;
1246:       player.ammo = player.mag;
1247:       sound.reloadEnd();
1248:       updateHud(true);
1249:     }
1250:   }
1251: 
1252:   if (wantFire && !player.reloading) {
1253:     if (player.ammo <= 0) startReload();
1254:     else if (player.fireCd <= 0) shoot();
1255:   }
1256: }
1257: 
1258: function applyAimAssist(dt) {
1259:   let target = null;
1260:   let bestScore = Infinity;
1261:   for (const zombie of enemies) {
1262:     if (zombie.dead) continue;
1263:     const dx = zombie.x - player.x;
1264:     const dy = zombie.y - player.y;
1265:     const distance = Math.hypot(dx, dy);
1266:     if (distance < 34 || distance > 620) continue;
1267:     const diff = Math.abs(angleWrap(Math.atan2(dy, dx) - player.aim));
1268:     if (diff > 0.24) continue;
1269:     const score = diff * 2.4 + distance / 1200;
1270:     if (score < bestScore) {
1271:       bestScore = score;
1272:       target = zombie;
1273:     }
1274:   }
1275:   if (!target) return;
1276:   const wanted = Math.atan2(target.y - player.y, target.x - player.x);
1277:   player.aim = angleLerp(player.aim, wanted, 1 - Math.exp(-dt * 4.2));
1278: }
1279: 
1280: function updateBullets(dt) {
1281:   for (let i = bullets.length - 1; i >= 0; i -= 1) {
1282:     const bullet = bullets[i];
1283:     bullet.x += bullet.vx * dt;
1284:     bullet.y += bullet.vy * dt;
1285:     bullet.life -= dt;
1286:     if (bullet.life <= 0 || bullet.x < 0 || bullet.y < 0 || bullet.x > WORLD.w || bullet.y > WORLD.h) {
1287:       bullets.splice(i, 1);
1288:       continue;
1289:     }
1290:     let hit = false;
1291:     for (const zombie of enemies) {
1292:       if (zombie.dead) continue;
1293:       const dx = zombie.x - bullet.x;
1294:       const dy = zombie.y - bullet.y;
1295:       if (dx * dx + dy * dy < (zombie.r + 3) * (zombie.r + 3)) {
1296:         damageZombie(zombie, bullet.dmg, bullet.angle);
1297:         hit = true;
1298:         break;
1299:       }
1300:     }
1301:     if (hit) bullets.splice(i, 1);
1302:   }
1303: 
1304:   for (let i = shells.length - 1; i >= 0; i -= 1) {
1305:     const shell = shells[i];
1306:     shell.life -= dt;
1307:     shell.x += shell.vx * dt;
1308:     shell.y += shell.vy * dt;
1309:     shell.vx *= Math.exp(-dt * 2.4);
1310:     shell.vy *= Math.exp(-dt * 2.4);
1311:     shell.rot += shell.spin * dt;
1312:     if (shell.life <= 0) shells.splice(i, 1);
1313:   }
1314: }
