1337:   const gained = zombie.score * multiplier;
1338:   game.score += gained;
1339:   game.shake = Math.min(12, game.shake + (zombie.type === "brute" ? 7 : 2));
1340:   bloodBurst(zombie.x, zombie.y, zombie.type === "brute" ? 30 : 15, zombie.type === "brute" ? 1.6 : 1);
1341:   addBloodDecal(zombie.x, zombie.y, zombie.type === "brute" ? 1.6 : zombie.type === "runner" ? 0.8 : 1.1, zombie.type === "brute" ? 10 : 6);
1342:   addText(zombie.x, zombie.y - zombie.r - 6, `+${gained}`, multiplier > 1 ? "#b7ff3e" : "#e8f1df", multiplier > 1 ? 15 : 12);
1343:   if (multiplier > 1) addText(zombie.x, zombie.y - zombie.r - 22, `x${multiplier}`, "#ffca57", 10);
1344: 
1345:   const dropRoll = Math.random();
1346:   if (zombie.type === "brute" || dropRoll < 0.11) dropPickup(zombie.x, zombie.y, "health");
1347:   else if (dropRoll < 0.2) dropPickup(zombie.x, zombie.y, "ammo");
1348: 
1349:   const direction = angle ?? rand(0, TAU);
1350:   for (let i = 0; i < (zombie.type === "brute" ? 7 : 3); i += 1) {
1351:     spawnParticle({
1352:       type: "chunk",
1353:       x: zombie.x,
1354:       y: zombie.y,
1355:       vx: Math.cos(direction + rand(-1.1, 1.1)) * rand(40, 200),
1356:       vy: Math.sin(direction + rand(-1.1, 1.1)) * rand(40, 200),
1357:       life: rand(0.5, 1.2),
1358:       size: rand(2, 5),
1359:       color: pick(["#4a1111", "#5f1914", "#2d1710"])
1360:     });
1361:   }
