867: function updateCamera(dt) {
868:   const bounds = cameraBounds();
869:   let targetX = player.x;
870:   let targetY = player.y;
871:   if (game.mode === "menu" || game.mode === "gameover") {
872:     targetX = WORLD.w / 2 + Math.sin(game.time * 0.12) * 85;
873:     targetY = WORLD.h / 2 + Math.cos(game.time * 0.1) * 60;
874:   }
875:   targetX = clamp(targetX, bounds.minX, bounds.maxX);
876:   targetY = clamp(targetY, bounds.minY, bounds.maxY);
877:   const smoothing = 1 - Math.exp(-dt * (game.mode === "menu" ? 2 : 7));
878:   camera.x += (targetX - camera.x) * smoothing;
879:   camera.y += (targetY - camera.y) * smoothing;
880: }
