1091:     maxHp: base.hp * hpScale,
1092:     speed: base.speed * speedScale,
1093:     dmg: base.dmg,
1094:     score: base.score,
1095:     angle: rand(0, TAU),
1096:     atkCd: rand(0, 0.4),
1097:     hitFlash: 0,
1098:     knockX: 0,
