1258: function applyAimAssist(dt) {
1259:   let target = null;
1260:   let bestScore = Infinity;
1261:   for (const zombie of enemies) {
1262:     if (zombie.dead) continue;
1263:     const dx = zombie.x - player.x;
1264:     const dy = zombie.y - player.y;
1265:     const distance = Math.hypot(dx, dy);
1266:     if (distance < 34 || distance > 620) continue;
1267:     const diff = Math.abs(angleWrap(Math.atan2(dy, dx) - player.aim));
1268:     if (diff > 0.24) continue;
1269:     const score = diff * 2.4 + distance / 1200;
1270:     if (score < bestScore) {
1271:       bestScore = score;
1272:       target = zombie;
1273:     }
1274:   }
1275:   if (!target) return;
1276:   const wanted = Math.atan2(target.y - player.y, target.x - player.x);
1277:   player.aim = angleLerp(player.aim, wanted, 1 - Math.exp(-dt * 4.2));
1278: }
