1602: function isVisible(x, y, padding = 80) {
1603:   const half = visibleHalf();
1604:   return x > camera.x - half.x - padding
1605:     && x < camera.x + half.x + padding
1606:     && y > camera.y - half.y - padding
1607:     && y < camera.y + half.y + padding;
1608: }
