1610: function render() {
1611:   const width = view.w;
1612:   const height = view.h;
1613:   ctx.setTransform(view.dpr, 0, 0, view.dpr, 0, 0);
1614:   ctx.fillStyle = "#070b08";
1615:   ctx.fillRect(0, 0, width, height);
1616: 
1617:   const shake = game.shake;
1618:   const shakeX = shake > 0 ? rand(-shake, shake) : 0;
1619:   const shakeY = shake > 0 ? rand(-shake, shake) : 0;
1620: 
1621:   ctx.save();
1622:   ctx.translate(width / 2 + shakeX, height / 2 + shakeY);
1623:   ctx.scale(view.scale, view.scale);
1624:   ctx.translate(-camera.x, -camera.y);
1625: 
1626:   if (!DEBUG.has("noground")) drawGround();
1627:   drawDecals();
1628:   if (!DEBUG.has("nofog")) drawFog();
1629:   drawPickups();
1630:   drawShells();
1631:   drawBullets();
1632: 
1633:   if (game.mode === "menu") {
1634:     for (const zombie of attractZombies) drawZombie(zombie);
1635:     drawPlayer(attractPlayer, false);
1636:   } else {
1637:     for (const zombie of enemies) {
1638:       if (!zombie.dead) drawZombie(zombie);
1639:     }
1640:     drawPlayer(player, true);
1641:   }
1642: 
1643:   drawParticles();
1644:   drawTexts();
1645:   if (game.mode === "playing" || game.mode === "dying") drawReticle();
1646:   ctx.restore();
1647: 
1648:   if (!DEBUG.has("noeffects")) drawScreenEffects(width, height);
1649: }
