1651: function drawGround() {
1652:   if (!worldCanvas) return;
1653:   const half = visibleHalf();
1654:   const sx = clamp(camera.x - half.x - 40, 0, WORLD.w);
1655:   const sy = clamp(camera.y - half.y - 40, 0, WORLD.h);
1656:   const ex = clamp(camera.x + half.x + 40, 0, WORLD.w);
1657:   const ey = clamp(camera.y + half.y + 40, 0, WORLD.h);
1658:   const sw = Math.max(1, ex - sx);
1659:   const sh = Math.max(1, ey - sy);
1660:   ctx.drawImage(worldCanvas, sx, sy, sw, sh, sx, sy, sw, sh);
1661: }
