569:   ui.motionBtn.setAttribute("aria-pressed", String(enabled));
570:   ui.motionLabel.textContent = enabled ? "INCLINAISON : ON" : "INCLINAISON : OFF";
571:   ui.calibrateBtn.classList.toggle("hidden", !enabled);
572:   ui.tiltBadge.classList.toggle("hidden", !enabled || game.mode !== "playing");
573:   if (enabled) {
574:     ui.motionHint.textContent = input.tilt.seen
575:       ? "Inclinez pour viser — le tir automatique reste actif. Recalibrez si besoin."
576:       : "Connexion au capteur de mouvement…";
577:   } else {
578:     ui.motionHint.textContent = "Optionnel — inclinez l'appareil pour viser, le tir devient automatique.";
579:   }
