166: const sound = (() => {
167:   let audio = null;
168:   let master = null;
169:   let noise = null;
170: 
171:   function ensure() {
172:     if (audio) {
173:       if (audio.state === "suspended") audio.resume().catch(() => {});
174:       return true;
175:     }
176:     const AudioCtx = window.AudioContext || window.webkitAudioContext;
177:     if (!AudioCtx) return false;
178:     try {
179:       audio = new AudioCtx();
180:       master = audio.createGain();
181:       master.gain.value = muted ? 0 : 0.32;
182:       master.connect(audio.destination);
183:       return true;
184:     } catch {
185:       return false;
186:     }
187:   }
188: 
189:   function getNoise() {
190:     if (!audio) return null;
191:     if (noise) return noise;
192:     const length = Math.floor(audio.sampleRate * 0.5);
193:     noise = audio.createBuffer(1, length, audio.sampleRate);
194:     const data = noise.getChannelData(0);
195:     for (let i = 0; i < length; i += 1) data[i] = Math.random() * 2 - 1;
196:     return noise;
197:   }
198: 
199:   function burst(duration = 0.08, volume = 0.12, frequency = 1200, type = "highpass", delay = 0) {
200:     if (!audio || muted) return;
201:     const buffer = getNoise();
202:     if (!buffer) return;
203:     const source = audio.createBufferSource();
204:     const filter = audio.createBiquadFilter();
205:     const gain = audio.createGain();
206:     const start = audio.currentTime + delay;
207:     source.buffer = buffer;
208:     filter.type = type;
209:     filter.frequency.setValueAtTime(frequency, start);
210:     gain.gain.setValueAtTime(0, start);
211:     gain.gain.linearRampToValueAtTime(volume, start + 0.006);
212:     gain.gain.exponentialRampToValueAtTime(0.0001, start + duration);
213:     source.connect(filter).connect(gain).connect(master);
214:     source.start(start);
215:     source.stop(start + duration + 0.02);
216:   }
217: 
218:   function tone(startFreq, endFreq, duration, type = "sawtooth", volume = 0.08, delay = 0) {
219:     if (!audio || muted) return;
220:     const start = audio.currentTime + delay;
221:     const oscillator = audio.createOscillator();
222:     const gain = audio.createGain();
223:     oscillator.type = type;
224:     oscillator.frequency.setValueAtTime(Math.max(20, startFreq), start);
225:     oscillator.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), start + duration);
226:     gain.gain.setValueAtTime(0, start);
227:     gain.gain.linearRampToValueAtTime(volume, start + 0.007);
228:     gain.gain.exponentialRampToValueAtTime(0.0001, start + duration);
229:     oscillator.connect(gain).connect(master);
230:     oscillator.start(start);
231:     oscillator.stop(start + duration + 0.03);
232:   }
233: 
234:   return {
235:     unlock() {
236:       if (!ensure()) return;
237:       if (audio.state === "suspended") audio.resume().catch(() => {});
238:     },
239:     setMuted(value) {
240:       muted = value;
241:       if (master) master.gain.value = muted ? 0 : 0.32;
242:     },
243:     shoot() {
244:       if (!ensure()) return;
245:       const pitch = rand(190, 235);
246:       burst(0.055, 0.16, 850);
247:       tone(pitch, 66, 0.075, "square", 0.045);
248:     },
249:     hit() {
250:       if (!ensure()) return;
251:       burst(0.035, 0.08, 1900, "bandpass");
252:       tone(135, 70, 0.05, "triangle", 0.035);
253:     },
254:     kill() {
255:       if (!ensure()) return;
256:       burst(0.16, 0.09, 420, "lowpass");
257:       tone(96, 38, 0.24, "sawtooth", 0.05);
258:     },
259:     hurt() {
260:       if (!ensure()) return;
261:       burst(0.16, 0.13, 260, "lowpass");
262:       tone(72, 33, 0.24, "sine", 0.12);
263:     },
264:     reloadStart() {
265:       if (!ensure()) return;
266:       burst(0.025, 0.06, 1500, "bandpass");
267:       burst(0.04, 0.05, 700, "bandpass", 0.22);
268:     },
269:     reloadEnd() {
270:       if (!ensure()) return;
271:       burst(0.025, 0.07, 2200, "bandpass");
272:     },
273:     pickup() {
274:       if (!ensure()) return;
275:       tone(620, 940, 0.09, "triangle", 0.07);
276:       tone(940, 1240, 0.1, "triangle", 0.045, 0.08);
277:     },
278:     wave() {
279:       if (!ensure()) return;
280:       tone(150, 150, 0.28, "sawtooth", 0.045);
281:       tone(225, 225, 0.34, "sawtooth", 0.035, 0.16);
282:     },
283:     over() {
284:       if (!ensure()) return;
285:       tone(210, 52, 0.9, "sawtooth", 0.09);
286:       tone(105, 44, 1.2, "sine", 0.1, 0.16);
287:       burst(0.5, 0.08, 220, "lowpass", 0.1);
288:     },
289:     click() {
290:       if (!ensure()) return;
291:       tone(420, 620, 0.045, "triangle", 0.035);
292:     }
293:   };
294: })();
