1085:   enemies.push({
1086:     type,
1087:     x: clamp(x, 30, WORLD.w - 30),
1088:     y: clamp(y, 30, WORLD.h - 30),
1089:     r: base.r,
1090:     hp: base.hp * hpScale,
1091:     maxHp: base.hp * hpScale,
1092:     speed: base.speed * speedScale,
1093:     dmg: base.dmg,
1094:     score: base.score,
1095:     angle: rand(0, TAU),
1096:     atkCd: rand(0, 0.4),
1097:     hitFlash: 0,
1098:     knockX: 0,
1099:     knockY: 0,
1100:     seed: rand(0, TAU),
1101:     dead: false
1102:   });
