1105: function updateWave(dt) {
1106:   game.spawnClock += dt;
1107:   if (game.waveState === "spawning") {
1108:     while (
1109:       game.spawnQueue.length > 0
1110:       && game.spawnQueue[0].at <= game.spawnClock
1111:       && enemies.length < 58
1112:     ) {
1113:       const next = game.spawnQueue.shift();
1114:       spawnEnemy(next.type);
1115:     }
1116:   }
1117: 
1118:   if (game.waveState === "spawning" && game.spawnQueue.length === 0 && enemies.length === 0) {
1119:     game.waveState = "break";
1120:     game.waveBreak = 3.15;
1121:     game.score += 35 * game.wave;
1122:     player.hp = Math.min(player.maxHp, player.hp + 8);
1123:     banner(`VAGUE ${String(game.wave).padStart(2, "0")}`, "ZONE NETTOYÉE", "+8 VITALITÉ · REPREND TON SOUFFLE");
1124:     sound.pickup();
1125:     if (Math.random() < 0.7) dropPickup(player.x + rand(-90, 90), player.y + rand(-90, 90), "health");
1126:   } else if (game.waveState === "break") {
1127:     game.waveBreak -= dt;
1128:     if (game.waveBreak <= 0) startWave(game.wave + 1);
1129:   }
1130: }
