1869:   ctx.lineTo(r * 1.18, -r * 0.4 + armSwing);
1870:   ctx.stroke();
1871:   ctx.beginPath();
1872:   ctx.moveTo(0, r * 0.42);
1873:   ctx.lineTo(r * 0.93, r * 0.55 - armSwing);
1874:   ctx.lineTo(r * 1.25, r * 0.36 - armSwing);
1875:   ctx.stroke();
1876: 
1877:   ctx.fillStyle = type.skin;
1878:   ctx.beginPath();
1879:   ctx.arc(r * 1.2, -r * 0.4 + armSwing, r * 0.16, 0, TAU);
1880:   ctx.arc(r * 1.27, r * 0.36 - armSwing, r * 0.16, 0, TAU);
1881:   ctx.fill();
1882: 
1883:   ctx.fillStyle = type.body;
1884:   ctx.beginPath();
1885:   ctx.ellipse(-r * 0.12, bob * 0.15, r * 0.86, r * 0.68, 0, 0, TAU);
1886:   ctx.fill();
1887: 
1888:   ctx.strokeStyle = "rgba(145, 170, 105, 0.2)";
1889:   ctx.lineWidth = 1;
1890:   ctx.beginPath();
1891:   ctx.moveTo(-r * 0.55, -r * 0.35);
1892:   ctx.lineTo(r * 0.2, r * 0.48);
1893:   ctx.moveTo(-r * 0.2, -r * 0.52);
1894:   ctx.lineTo(r * 0.32, r * 0.3);
1895:   ctx.stroke();
1896: 
1897:   ctx.fillStyle = type.skin;
1898:   ctx.beginPath();
1899:   ctx.arc(r * 0.46, 0, r * 0.46, 0, TAU);
1900:   ctx.fill();
1901:   ctx.fillStyle = "rgba(22, 27, 18, 0.6)";
1902:   ctx.beginPath();
1903:   ctx.arc(r * 0.42, -r * 0.06, r * 0.3, 0, TAU);
1904:   ctx.fill();
1905: 
1906:   const eyeX = r * 0.72;
1907:   ctx.fillStyle = type.eye;
1908:   ctx.beginPath();
1909:   ctx.arc(eyeX, -r * 0.16, r * 0.075, 0, TAU);
1910:   ctx.arc(eyeX, r * 0.16, r * 0.075, 0, TAU);
1911:   ctx.fill();
1912: 
1913:   if (zombie.type === "brute") {
1914:     ctx.strokeStyle = "rgba(40, 25, 22, 0.8)";
1915:     ctx.lineWidth = 2;
1916:     ctx.beginPath();
1917:     ctx.arc(-r * 0.1, 0, r * 0.76, 0.4, 2.7);
1918:     ctx.stroke();
1919:   }
1920: 
1921:   if (flash > 0) {
1922:     ctx.globalCompositeOperation = "lighter";
1923:     ctx.fillStyle = `rgba(255, 245, 220, ${flash * 0.34})`;
1924:     ctx.beginPath();
1925:     ctx.ellipse(-r * 0.08, 0, r * 0.92, r * 0.74, 0, 0, TAU);
1926:     ctx.fill();
1927:     ctx.beginPath();
1928:     ctx.arc(r * 0.46, 0, r * 0.5, 0, TAU);
1929:     ctx.fill();
1930:   }
1931: 
1932:   if (zombie.type === "brute" && zombie.hp < zombie.maxHp) {
1933:     const ratio = clamp(zombie.hp / zombie.maxHp, 0, 1);
1934:     ctx.rotate(-zombie.angle);
