2171:   ctx.lineTo(target.x, target.y);
2172:   ctx.stroke();
2173:   ctx.setLineDash([]);
2174: 
2175:   const pulse = 1 + Math.sin(game.time * 4.5) * 0.06;
2176:   ctx.translate(target.x, target.y);
2177:   ctx.rotate(game.time * 0.35);
