490:     const cos = Math.cos(radians);
491:     const sin = Math.sin(radians);
492:     const rotatedX = dx * cos + dy * sin;
493:     const rotatedY = -dx * sin + dy * cos;
494:     dx = rotatedX;
495:     dy = rotatedY;
496:   }
497: 
498:   if (Math.hypot(dx, dy) > 3.6) {
499:     input.tilt.angle = Math.atan2(dy, dx);
500:     input.tilt.active = true;
501:   } else {
502:     input.tilt.active = false;
503:   }
504: }
