1321:   zombie.knockX += Math.cos(angle) * force;
1322:   zombie.knockY += Math.sin(angle) * force;
1323:   const headX = zombie.x + Math.cos(zombie.angle) * zombie.r * 0.35;
1324:   const headY = zombie.y + Math.sin(zombie.angle) * zombie.r * 0.35;
