1376: function updateZombies(dt) {
1377:   const count = enemies.length;
1378:   for (const zombie of enemies) {
1379:     if (zombie.dead) continue;
1380:     zombie.hitFlash = Math.max(0, zombie.hitFlash - dt * 4.5);
1381:     zombie.atkCd = Math.max(0, zombie.atkCd - dt);
1382:     zombie.knockX *= Math.exp(-dt * 7);
1383:     zombie.knockY *= Math.exp(-dt * 7);
1384: 
1385:     const dx = player.x - zombie.x;
1386:     const dy = player.y - zombie.y;
1387:     const distance = Math.hypot(dx, dy) || 1;
1388:     const targetAngle = Math.atan2(dy, dx);
1389:     const turnSpeed = zombie.type === "runner" ? 7 : zombie.type === "brute" ? 3.2 : 4.8;
1390:     zombie.angle = angleLerp(zombie.angle, targetAngle, 1 - Math.exp(-dt * turnSpeed));
1391: 
1392:     const wobbleAmount = zombie.type === "runner" ? 0.22 : zombie.type === "brute" ? 0.08 : 0.14;
1393:     const wobble = Math.sin(game.time * 2.7 + zombie.seed) * wobbleAmount;
1394:     const moveAngle = zombie.angle + wobble;
1395:     const speed = zombie.speed;
1396: 
1397:     let vx = Math.cos(moveAngle) * speed + zombie.knockX;
1398:     let vy = Math.sin(moveAngle) * speed + zombie.knockY;
1399: 
1400:     if (count < 45) {
1401:       for (const other of enemies) {
1402:         if (other === zombie || other.dead) continue;
1403:         const ox = zombie.x - other.x;
1404:         const oy = zombie.y - other.y;
1405:         const minDistance = zombie.r + other.r;
1406:         const dist2 = ox * ox + oy * oy;
1407:         if (dist2 > 0.01 && dist2 < minDistance * minDistance) {
1408:           const dist = Math.sqrt(dist2);
1409:           const push = (minDistance - dist) / minDistance;
1410:           vx += ox / dist * push * 70;
1411:           vy += oy / dist * push * 70;
1412:         }
1413:       }
1414:     }
1415: 
1416:     zombie.x = clamp(zombie.x + vx * dt, 22, WORLD.w - 22);
1417:     zombie.y = clamp(zombie.y + vy * dt, 22, WORLD.h - 22);
1418: 
1419:     if (distance < zombie.r + player.r && zombie.atkCd <= 0 && player.invuln <= 0) {
1420:       hurtPlayer(zombie);
1421:       zombie.atkCd = 0.9;
1422:     }
1423:   }
1424: }
